vector<int> g[100];
int dist[100];
int n, m;
void bfs(int s) {
    memset(dist, -1, sizeof(dist));
    queue<int> q;
    q.push(s);
    dist[s] = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : g[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
}
int main() {
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d%d", &u, &v);
        g[u].push_back(v);
        g[v].push_back(u);
    }
    int ans = 0;
    for (int i = 1; i <= n; ++i) {
        bfs(i);
        for (int j = 1; j <= n; ++j) {
            if (dist[j] > ans) ans = dist[j];
        }
    }
    printf("%d\n", ans);
    return 0;
}
